export class ClipPlayer{
 constructor(onStatus=()=>{}){this.onStatus=onStatus;this.Context=globalThis.AudioContext||globalThis.webkitAudioContext;this.available=!!this.Context||typeof globalThis.Audio==='function';this.cache=new Map();this.sources=[];this.generation=0;this.state={speaking:false,paused:false,loading:false};}
 status(){return {...this.state};}
 emit(extra={}){this.state={...this.state,...extra};this.onStatus(this.status());}
 async buffer(src){if(this.cache.has(src))return this.cache.get(src);const promise=(async()=>{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);let response;try{response=await fetch(src,{credentials:'same-origin',signal:controller.signal});}finally{clearTimeout(timer);}if(!response.ok)throw Error('Không tải được âm thanh tiếng Việt ('+response.status+').');const bytes=await response.arrayBuffer();return this.context.decodeAudioData(bytes);})();this.cache.set(src,promise);try{const result=await promise;if(this.cache.size>3){const oldest=this.cache.keys().next().value;if(oldest!==src)this.cache.delete(oldest);}return result;}catch(error){this.cache.delete(src);throw error;}}
 play(clips,rate=1){if(!this.available||!clips?.length)return {ok:false,reason:'Chưa có đoạn âm thanh phù hợp.'};this.stop();const generation=this.generation;this.emit({loading:true,speaking:false,paused:false});this.rate=Math.max(.6,Math.min(1.4,+rate||1));if(!this.Context){this.nativePlay(clips,generation);return {ok:true};}try{this.context=this.context||new this.Context();const resumed=this.context.resume();Promise.resolve(resumed).catch(()=>{});this.prepare(clips,generation,resumed);}catch(error){if(typeof globalThis.Audio==='function'){this.Context=null;this.nativePlay(clips,generation);return {ok:true};}this.emit({loading:false,error:'Không mở được âm thanh. Hãy bấm Nghe lại.'});return {ok:false,reason:'Thiết bị chưa mở được âm thanh.'};}return {ok:true};}
 async prepare(clips,generation,resumed){try{await resumed;const buffers=await Promise.all(clips.map(c=>this.buffer(c.src)));if(generation!==this.generation)return;let when=this.context.currentTime+.04;this.sources=clips.map((clip,i)=>{const buffer=buffers[i],start=Math.max(0,clip.start||0),end=Math.min(buffer.duration,clip.end??buffer.duration),duration=end-start;if(!(duration>0))throw Error('Đoạn đọc không có âm thanh.');const source=this.context.createBufferSource();source.buffer=buffer;source.playbackRate.value=this.rate;source.connect(this.context.destination);source.start(when,start,duration);when+=duration/this.rate+(clip.gap??.035);return source;});this.sources.at(-1).onended=()=>{if(generation===this.generation)this.emit({speaking:false,loading:false,paused:false});};this.emit({loading:false,speaking:true});}catch(error){if(generation!==this.generation)return;this.sources.forEach(s=>{try{s.stop()}catch{}});this.emit({loading:false,speaking:false,paused:false,error:/^Không tải được âm thanh/.test(error.message)?error.message:'Chưa phát được giọng Việt. Kiểm tra kết nối rồi bấm Nghe lại.'});}}
 nativePlay(clips,generation,index=0){if(generation!==this.generation)return;if(index>=clips.length){this.emit({speaking:false,loading:false,paused:false});return;}const clip=clips[index],audio=this.nativeAudio=new Audio(clip.src);audio.preload='auto';let finished=false;const next=()=>{if(finished||generation!==this.generation)return;finished=true;audio.pause();clearTimeout(this.nativeTimer);this.nativePlay(clips,generation,index+1);};audio.onloadedmetadata=()=>{if(generation===this.generation)audio.currentTime=clip.start||0;};audio.onplaying=()=>{if(generation!==this.generation)return audio.pause();this.emit({loading:false,speaking:true});clearTimeout(this.nativeTimer);if(clip.end)this.nativeTimer=setTimeout(next,Math.max(0,(clip.end-audio.currentTime)/this.rate*1000));};audio.ontimeupdate=()=>{if(clip.end&&audio.currentTime>=clip.end)next();};audio.onended=next;audio.onerror=()=>{if(generation===this.generation)this.emit({loading:false,speaking:false,error:'Không tải được âm thanh tiếng Việt. Thử lại khi có mạng.'});};audio.playbackRate=this.rate;audio.play().catch(()=>{if(generation===this.generation)this.emit({loading:false,speaking:false,error:'Hãy bấm Nghe lại để cho phép phát âm thanh.'});});}
 togglePause(){if(!this.state.speaking&&!this.state.loading)return;const paused=!this.state.paused;if(this.Context&&this.context){const action=paused?this.context.suspend():this.context.resume();Promise.resolve(action).catch(()=>{});}else if(this.nativeAudio){clearTimeout(this.nativeTimer);if(paused)this.nativeAudio.pause();else this.nativeAudio.play().catch(()=>{});}this.emit({paused});}
 stop(){this.generation++;clearTimeout(this.nativeTimer);this.nativeAudio?.pause();this.nativeAudio=null;for(const source of this.sources){try{source.stop()}catch{}source.disconnect?.();}this.sources=[];this.emit({speaking:false,paused:false,loading:false,error:undefined});}
}
